     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    private final Rooms rooms;
    13	    private final ReservationStore store;
    14	    private final PriceCalculator priceCalculator;
    15	    private final List<ReservationListener> listeners;
    16	
    17	    public ReservationService(
    18	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, List<ReservationListener> listeners) {
    19	        this.rooms = rooms;
    20	        this.store = store;
    21	        this.priceCalculator = priceCalculator;
    22	        this.listeners = List.copyOf(listeners);
    23	    }
    24	
    25	    public synchronized Reservation create(NewReservation request) {
    26	        if (!request.checkOut().isAfter(request.checkIn())) {
    27	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    28	        }
    29	        if (request.guests() < 1) {
    30	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    31	        }
    32	        Room room = rooms.find(request.roomNumber())
    33	                .orElseThrow(() -> new HotelException(
    34	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    35	        if (request.guests() > room.capacity()) {
    36	            throw new HotelException(
    37	                    ErrorCode.CAPACITY_EXCEEDED,
    38	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    39	        }
    40	        boolean roomTaken = store.all().stream()
    41	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
    42	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
    43	        if (roomTaken) {
    44	            throw new HotelException(
    45	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    46	        }
    47	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    48	        Reservation reservation = new Reservation(store.nextId(), request, price);
    49	        store.save(reservation);
    50	        return reservation;
    51	    }
    52	
    53	    public Reservation find(long reservationId) {
    54	        return store.find(reservationId)
    55	                .orElseThrow(() -> new HotelException(
    56	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    57	    }
    58	
    59	    /** The guest paid: the reservation is confirmed and listeners are notified. */
    60	    public synchronized Reservation confirm(long reservationId) {
    61	        Reservation reservation = find(reservationId);
    62	        if (reservation.status() != ReservationStatus.PENDING) {
    63	            throw notAllowed(reservation, "confirm");
    64	        }
    65	        reservation.confirmPayment();
    66	        Room room = roomOf(reservation);
    67	        for (ReservationListener listener : listeners) {
    68	            listener.onReservationConfirmed(reservation, room);
    69	        }
    70	        return reservation;
    71	    }
    72	
    73	    /**
    74	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    75	     * reservation was never paid, so nothing comes back). Listeners are notified.
    76	     */
    77	    public synchronized Reservation cancel(long reservationId) {
    78	        Reservation reservation = find(reservationId);
    79	        if (reservation.status() != ReservationStatus.PENDING
    80	                && reservation.status() != ReservationStatus.CONFIRMED) {
    81	            throw notAllowed(reservation, "cancel");
    82	        }
    83	        BigDecimal refund = switch (reservation.ratePlan()) {
    84	            case STANDARD -> reservation.amountPaid();
    85	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    86	        };
    87	        reservation.cancel(refund);
    88	        Room room = roomOf(reservation);
    89	        for (ReservationListener listener : listeners) {
    90	            listener.onReservationCancelled(reservation, room);
    91	        }
    92	        return reservation;
    93	    }
    94	
    95	    public synchronized Reservation checkIn(long reservationId) {
    96	        Reservation reservation = find(reservationId);
    97	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    98	            throw notAllowed(reservation, "check in");
    99	        }
   100	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   101	        return reservation;
   102	    }
   103	
   104	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   105	    public synchronized ReservationReceipt checkOut(long reservationId) {
   106	        Reservation reservation = find(reservationId);
   107	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   108	            throw notAllowed(reservation, "check out");
   109	        }
   110	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   111	        return new ReservationReceipt(reservation, roomOf(reservation));
   112	    }
   113	
   114	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   115	    public ReservationReceipt receiptCopy(long reservationId) {
   116	        Reservation reservation = find(reservationId);
   117	        if (!reservation.isPaid()) {
   118	            throw notAllowed(reservation, "issue a receipt for");
   119	        }
   120	        return new ReservationReceipt(reservation, roomOf(reservation));
   121	    }
   122	
   123	    private Room roomOf(Reservation reservation) {
   124	        return rooms.find(reservation.roomNumber()).orElseThrow();
   125	    }
   126	
   127	    private static HotelException notAllowed(Reservation reservation, String operation) {
   128	        return new HotelException(
   129	                ErrorCode.OPERATION_NOT_ALLOWED,
   130	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   131	    }
   132	}
